INSERT INTO changelog (title, body, created_at) VALUES ('Стартапи: карта продукту, назва й опис', 'У стартапі на «Огляді» внизу зʼявилась «Карта продукту»: як він виглядатиме в кінцевому рахунку. Що це і що дає; для кого і який біль; чим кращі за альтернативи; з чого складається (модулі зі статусом); інтеграції й фундамент; як продаємо; ціна і гроші (прибуток за рік, вихід у нуль); що вже знаємо; шлях до готового. Порожні блоки обведені пунктиром, стрілка веде на вкладку, де їх заповнити. «Джері, добудуй карту» заповнить, що може.
Зверху карти — «✎ Назва і опис»: тут даєш назву продукту і описуєш, що це, для кого і що дає.', datetime('now'));
